UPDATE stellar_coupon
name = #{name}, type = #{type}, condition_amount = #{conditionAmount}, discount_amount = #{discountAmount}, total_count = #{totalCount}, per_user_limit = #{perUserLimit}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser}
WHERE id = #{id}

mapper.select:
SELECT * FROM stellar_coupon

    AND name LIKE CONCAT('%', #{name}, '%')
    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM stellar_coupon

    AND name LIKE CONCAT('%', #{name}, '%')
    AND status = #{status}

mapper.update:
UPDATE stellar_user_coupon SET status = #{status}
, order_id = #{orderId}
, used_time = #{usedTime}
, update_time = NOW()
WHERE id = #{id} AND status = 1

mapper.select:
SELECT uc.*, c.name AS coupon_name, c.type AS coupon_type, c.condition_amount, c.discount_amount, c.start_time, c.end_time
FROM stellar_user_coupon uc
LEFT JOIN stellar_coupon c ON c.id = uc.coupon_id
WHERE uc.user_id = #{userId}
AND uc.status = #{status}
ORDER BY uc.create_time DESC
